import test from 'node:test';import assert from 'node:assert/strict';
import {STATIONS} from './data.mjs';import {SPAWN,createWorld,canWalk,findPath,nearestStation,loadProgress,saveProgress} from './world.mjs';
const world=createWorld();
test('every résumé landmark is reachable from the dock without walking through objects',()=>{for(const s of STATIONS){const route=findPath(world,SPAWN,{x:s.door[0],y:s.door[1]});assert.ok(route.length,s.name);let last=SPAWN;for(const p of route){assert.ok(canWalk(world,p.x,p.y));assert.equal(Math.abs(p.x-last.x)+Math.abs(p.y-last.y),1);last=p;}assert.equal(last.x,s.door[0]);assert.equal(last.y,s.door[1]);assert.equal(nearestStation(last.x,last.y)?.id,s.id);}});
test('every pair of landmarks has a navigable route',()=>{for(const a of STATIONS)for(const b of STATIONS){if(a===b)continue;assert.ok(findPath(world,{x:a.door[0],y:a.door[1]},{x:b.door[0],y:b.door[1]}).length,`${a.id} → ${b.id}`);}});
test('buildings, trees, and world boundaries block travel',()=>{assert.equal(canWalk(world,-1,0),false);assert.equal(canWalk(world,42,20),false);for(const s of STATIONS)assert.equal(canWalk(world,s.x+2,s.y+2),false);for(const d of world.decor.filter(d=>d.kind==='tree'))assert.equal(canWalk(world,d.x,d.y),false);assert.deepEqual(findPath(world,SPAWN,{x:9,y:9}),[]);});
test('canal and bridge can both be crossed by a fish',()=>{assert.ok(canWalk(world,20,19));assert.ok(canWalk(world,22,19));assert.ok(findPath(world,{x:20,y:17},{x:20,y:22}).length);});
test('unknown or corrupt saved data cannot unlock résumé scales',()=>{for(const value of ['null','{}','42','bad json'])assert.equal(loadProgress({getItem:()=>value}).size,0);assert.deepEqual([...loadProgress({getItem:()=>JSON.stringify(['work','evil','work','contact'])})],['work','contact']);});
test('storage failures do not stop the game and valid progress round-trips',()=>{const fail={getItem(){throw Error();},setItem(){throw Error();}};assert.equal(loadProgress(fail).size,0);assert.equal(saveProgress(fail,new Set(['work'])),false);let value='';const store={getItem:()=>value,setItem:(_,v)=>{value=v;}};saveProgress(store,new Set(STATIONS.map(s=>s.id)));assert.equal(loadProgress(store).size,6);});
test('all résumé links use supported destinations',()=>{for(const s of STATIONS){assert.ok(s.chapters.length);for(const link of [...s.links,...s.chapters.flatMap(c=>c.links||[])])assert.match(link.href,/^(https:\/\/|\/|mailto:)/);}});
